theorem Std.TreeSet.Equiv.getGED_eq.{u} {α : Type u} {cmp : α → α → Ordering} {t₁ t₂ : Std.TreeSet α cmp}
  [Std.TransCmp cmp] {k fallback : α} (h : t₁.Equiv t₂) :
  t₁.getGED k fallback = t₂.getGED k fallback

theorem Std.TreeSet.get!_inter.{u} {α : Type u} {cmp : α → α → Ordering} {t₁ t₂ : Std.TreeSet α cmp}
  [Std.TransCmp cmp] [Inhabited α] {k : α} :
  (t₁ ∩ t₂).get! k = if k ∈ t₂ then t₁.get! k else default

theorem Std.TreeSet.get!_inter_of_mem_right.{u} {α : Type u} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.TreeSet α cmp} [Std.TransCmp cmp] [Inhabited α] {k : α} (mem : k ∈ t₂) :
  (t₁ ∩ t₂).get! k = t₁.get! k

theorem Std.TreeSet.getD_congr.{u} {α : Type u} {cmp : α → α → Ordering} {t : Std.TreeSet α cmp}
  [Std.TransCmp cmp] {k k' fallback : α} (h' : cmp k k' = Ordering.eq) :
  t.getD k fallback = t.getD k' fallback

theorem Std.TreeSet.maxD_insert.{u} {α : Type u} {cmp : α → α → Ordering} {t : Std.TreeSet α cmp}
  [Std.TransCmp cmp] {k fallback : α} :
  (t.insert k).maxD fallback = t.max?.elim k fun k' => if cmp k' k = Ordering.lt then k else k'

theorem Std.TreeSet.get?_eq_some_get!_of_contains.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.TreeSet α cmp} [Std.TransCmp cmp] [Inhabited α] {a : α} :
  t.contains a = true → t.get? a = some (t.get! a)
